<script>
function searchRestaurants(){let term=document.getElementById('searchInput').value.trim().toLowerCase();let cards=document.querySelectorAll('#restaurantGrid .restaurant-card');let count=0;cards.forEach(function(card){let text=card.dataset.name+' '+card.dataset.type+' '+card.dataset.foods;let show=text.includes(term);card.style.display=show?'':'none';if(show)count++;});document.getElementById('noResults').style.display=count===0?'block':'none';}
function filterCategory(type){document.getElementById('searchInput').value='';let cards=document.querySelectorAll('#restaurantGrid .restaurant-card');let count=0;cards.forEach(function(card){let show=type==='All'||card.dataset.type===type.toLowerCase()||card.dataset.foods.includes(type.toLowerCase());card.style.display=show?'':'none';if(show)count++;});document.getElementById('noResults').style.display=count===0?'block':'none';}
document.getElementById('searchInput').addEventListener('input',searchRestaurants);
let cart=JSON.parse(sessionStorage.getItem('timedCart')||'[]');document.getElementById('cartCount').textContent=cart.reduce((sum,item)=>sum+item.quantity,0);
</script></body></html>